import { Table, StringColumn, JsonColumn, ScriptColumn, ReferenceColumn, GenericColumn } from '../../db'

export const sys_alias_templates = Table({
    name: 'sys_alias_templates',
    extends: 'sys_metadata',
    label: 'Connection & Credential Templates',
    allowWebServiceAccess: true,
    schema: {
        name: StringColumn({
            mandatory: true,
            label: 'Name',
            attributes: {
                edge_encryption_enabled: true,
            },
            maxLength: 100,
        }),
        dynamic_data_schema: JsonColumn({
            mandatory: true,
            label: 'Dynamic Data Schema',
            attributes: {
                json_view: true,
            },
            maxLength: 10000,
        }),
        default_data_template: JsonColumn({
            mandatory: true,
            label: 'Default Data Template',
            attributes: {
                json_view: true,
            },
            maxLength: 10000,
        }),
        pre_edit_script: ScriptColumn({
            mandatory: false,
            label: 'Pre-Edit Script',
            maxLength: 8000,
        }),
        on_edit_script: ScriptColumn({
            mandatory: false,
            label: 'On Edit Script',
            maxLength: 8000,
        }),
        post_process_script: ScriptColumn({
            mandatory: false,
            label: 'On Create Script',
            maxLength: 8000,
        }),
        test_action: ReferenceColumn({
            mandatory: false,
            label: 'Test Action',
            attributes: {
                encode_utf8: false,
            },
            referenceTable: 'sys_hub_action_type_definition',
        }),
        sys_id: GenericColumn({
            mandatory: false,
            label: 'Sys ID',
            column_type: 'GUID',
        }),
    },
})
